 static void receive(void*p,const codec::PacketView&,const memory::RxEnvelope&)noexcept{auto& c=*static_cast<Callback*>(p);c.called=true;auto nested=c.adapter->progress_next();c.nested_rejected=!nested&&nested.error().code==ErrorCode::would_deadlock;c.adapter->begin_cycle();auto token=c.ticket.reserve(1);if(!token)return;auto accepted=c.adapter->try_send({storage(c.txpool,verify_p12::signal),std::move(*token),{7,1},{7,0x01020304,codec::PacketType::signal}});c.queued=bool(accepted);}
